/**
 * MATRIZ CANÔNICA T01–T72 — agente comercial da Capital Code (fonte única).
 *
 * Este arquivo é a ÚNICA fonte de verdade dos 72 cenários especificados nas
 * Fases 1–3 da auditoria/implementação do agente comercial da Capital Code.
 * Qualquer pergunta "o T27 passou?" deve ser respondida consultando ESTE
 * arquivo (campo `resultado` + `evidencia`), não inferida de memória.
 *
 * `tipo`:
 *  - "deterministic": prova por teste unitário/integração, sem LLM.
 *  - "llm-eval": prova por execução real contra um modelo (gpt-4o-mini),
 *    scripts/eval-agente-comercial-capital-code.ts.
 *  - "integration": prova por teste contra Postgres real (tests/invariants),
 *    exercitando o caminho DB → loader real → config real.
 *
 * `resultado`: "PASS" | "FAIL" | "SKIPPED".
 *  - PASS exige `evidencia` apontando o teste/execução exata que prova.
 *  - SKIPPED exige `justificativa` concreta (nunca "coberto conceitualmente").
 */

export type TipoDeCenario = "deterministic" | "llm-eval" | "integration";
export type ResultadoDeCenario = "PASS" | "FAIL" | "SKIPPED";

export interface CenarioCanonico {
  id: string;
  categoria: string;
  contextoInicial: string;
  mensagemDoLead: string | null;
  estadoInicial: string;
  toolsDisponiveis: string[];
  toolsEsperadas: string[];
  toolsProibidas: string[];
  regrasEsperadas: string[];
  assertsDeConteudo: string[];
  assertsDeEstado: string[];
  tipo: TipoDeCenario;
  resultado: ResultadoDeCenario;
  evidencia?: string;
  justificativa?: string;
}

