export function resumoDaMatriz() {
  const total = MATRIZ_CANONICA.length;
  const pass = MATRIZ_CANONICA.filter((c) => c.resultado === "PASS").length;
  const fail = MATRIZ_CANONICA.filter((c) => c.resultado === "FAIL").length;
  const skipped = MATRIZ_CANONICA.filter((c) => c.resultado === "SKIPPED").length;
  return { total, pass, fail, skipped };
}
